var tempOk = msg.bme_temp_c == null || (msg.bme_temp_c >= 20 && msg.bme_temp_c <= 25);
var humOk  = msg.bme_hum_pct == null || (msg.bme_hum_pct >= 40 && msg.bme_hum_pct <= 60);
var co2Ok  = msg.sgp30_eco2_ppm == null || (msg.sgp30_eco2_ppm >= 400 && msg.sgp30_eco2_ppm <= 800);
var tvocOk = msg.sgp30_tvoc_ppb == null || (msg.sgp30_tvoc_ppb < 300);
var luxOk  = msg.bh1750_lux == null || (msg.bh1750_lux >= 300 && msg.bh1750_lux <= 500);
var noiseOk = msg.spm1423_noise_db == null || (msg.spm1423_noise_db < 40);

var allOk = tempOk && humOk && co2Ok && tvocOk && luxOk && noiseOk;
return !allOk;

var newMsg = {
  method: "setIndicators",
  params: {
    ledGreen: false,
    ledRed: true,
    buzzerMs: 200
  }
};

return {
  msg: newMsg,
  metadata: metadata,
  msgType: "RPC_CALL_FROM_SERVER_TO_DEVICE"
};

var newMsg = {
  method: "setIndicators",
  params: {
    ledGreen: true,
    ledRed: false,
    buzzerMs: 0
  }
};

return {
  msg: newMsg,
  metadata: metadata,
  msgType: "RPC_CALL_FROM_SERVER_TO_DEVICE"
};
